{"preview_rows": 5, "sql": "WITH cleaned AS (
  SELECT 
    CompanyName,
    Location,
    Salary,
    TRY_CAST(
      REPLACE(
        REPLACE(
          REPLACE(
            REPLACE(
              SUBSTR(Salary, 2),
            ',',''
          ), '/yr', ''
        ), '/mo', ''
      ), '/hr', ''
    ) AS salary_numeric
  FROM SalaryDataset
  WHERE Location IN ('Mumbai', 'Pune', 'New Delhi', 'Hyderabad')
)
SELECT Salary, salary_numeric FROM cleaned WHERE salary_numeric IS NULL"}
